#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# founder-vn harness setup (docs/agents/kiro-harness.md §7, the human prerequisites H-1…H-7).
# Repeatable: committed at scripts/harness/setup-wizard.sh so the next operator runs it instead
# of re-reading the harness document. `--list` prints the stages without asking anything.

REPO="NHAN-AI-VN/founder-vn"
ORG="NHAN-AI-VN"
STAGE_NAMES=(
  "Preflight: gh, repository, branch"
  "H-1 · Kiro Agent GitHub App covers $REPO"
  "H-2 · Kiro Web: project connected, sandbox env FOUNDER_LLM_*, internet, PR author"
  "H-3 · Dispatch token (fine-grained) → secret HARNESS_DISPATCH_TOKEN"
  "H-4 · Repository variables HARNESS_WEB_REVIEW and HARNESS_DISPATCH"
  "H-5 · Actions permissions (check only)"
  "H-6 · PyPI trusted publisher for founder-vn (optional, needed by T01)"
  "H-7 · Ticket #5 (T04, ready-for-human) and a dry run of the dispatcher"
  "H-8 · Protect main on GitHub (the guard does not run in the Kiro Web sandbox)"
  "H-9 · Start the loop: workflows enabled, HARNESS_DISPATCH=on"
)

run_wizard() {

TOTAL_STAGES=${#STAGE_NAMES[@]}

if [[ "${1:-}" == "--list" ]]; then
  printf 'founder-vn harness setup: %s stages\n' "$TOTAL_STAGES"
  local i=0; for s in "${STAGE_NAMES[@]}"; do i=$((i + 1)); printf '  %s. %s\n' "$i" "$s"; done
  printf '\nValues produced: secret HARNESS_DISPATCH_TOKEN, variables HARNESS_WEB_REVIEW and HARNESS_DISPATCH, local %s with FOUNDER_LLM_BASE_URL and FOUNDER_LLM_MODEL (and the key, hidden), branch protection on main. The rest are checks and actions.\n' "$ENV_FILE"
  return 0
fi

# Run from the repository root whatever the current directory: gh secret/variable without --repo
# read the clone's origin, and the dry run below needs the harness scripts.
cd "$(dirname "${BASH_SOURCE[0]}")/../.."

banner "founder-vn harness setup"

# ── 1 ────────────────────────────────────────────────────────────────────────
stage "${STAGE_NAMES[0]}"
say "The harness lives in this clone; the loop runs on GitHub Actions and Kiro Web."
if ! command -v gh >/dev/null 2>&1 || ! gh auth status >/dev/null 2>&1; then
  warn "gh is not installed or not logged in. Run: gh auth login"
  pause "Press Enter once gh auth status is green (or Ctrl-C to stop)."
fi
local who; who=$(gh api user --jq .login 2>/dev/null || echo unknown)
say "gh is logged in as: $who (the operator of docs/agents/kiro-harness.md, HARNESS_OPERATOR=nhannguyen89)"
local slug; slug=$(gh repo view --json nameWithOwner --jq .nameWithOwner 2>/dev/null || echo unknown)
if [[ "$slug" != "$REPO" ]]; then warn "this clone points at $slug, expected $REPO"; else say "repository: $slug"; fi
local hb; hb=$(gh api "repos/$REPO/contents/scripts/harness/dispatch.sh?ref=main" --jq .sha 2>/dev/null || true)
if [[ -z "$hb" ]]; then
  warn "scripts/harness/ is not on main yet: merge the bootstrap pull request (harness/bootstrap) first, by hand (FV-D4)."
  pause "Press Enter once it is merged, or continue anyway to prepare the credentials."
else
  say "harness scripts are on main."
fi

# ── 2 ────────────────────────────────────────────────────────────────────────
stage "${STAGE_NAMES[1]}"
say "Kiro Web reacts to the /kiro comments of the dispatcher only on a repository its GitHub App can see."
local apps; apps=$(gh api "orgs/$ORG/installations" --jq '.installations[] | "\(.app_slug) (\(.repository_selection))"' 2>/dev/null || true)
if printf '%s\n' "$apps" | grep -q '^kiro-agent (all)'; then
  say "Kiro Agent app is installed on $ORG for all repositories: $REPO is covered."
elif printf '%s\n' "$apps" | grep -q '^kiro-agent'; then
  warn "Kiro Agent app is installed on $ORG for selected repositories only."
  open_url "https://github.com/organizations/$ORG/settings/installations"
  step "Open the Kiro Agent installation → Repository access → add founder-vn → Save."
  pause "Press Enter when founder-vn is in the list."
else
  warn "No kiro-agent installation found on $ORG (or you lack permission to list them)."
  open_url "https://github.com/organizations/$ORG/settings/installations"
  step "Install the Kiro Agent GitHub App for $ORG (from app.kiro.dev → Settings → Agent → GitHub, 'Connect GitHub'), granting founder-vn."
  pause "Press Enter when the app shows under Installed GitHub Apps."
fi

# ── 3 ────────────────────────────────────────────────────────────────────────
stage "${STAGE_NAMES[2]}"
say "Kiro Web runs each lane in a sandbox on a checkout of this repository. The sandbox needs the model"
say "credentials the package reads (FV-D3) and open internet (uv install, PyPI, the model endpoint)."
note "UI paths below follow the Kiro Web settings as nhan recorded them in September 2026 (Settings → Agent →"
note "GitHub; project settings for environment variables and internet access). If the UI differs, follow the equivalent."
open_url "https://app.kiro.dev"
step "Settings → Agent → GitHub: make sure $REPO is connected (add it if the list lacks it)."
step "Project settings for $REPO → environment variables: add FOUNDER_LLM_BASE_URL, FOUNDER_LLM_API_KEY, FOUNDER_LLM_MODEL."
step "Project settings → internet access: open (not 'common dependencies only')."
step "Settings → Agent: 'Create pull requests as your GitHub user' ON (the lane's pull requests then carry your account, which the merger expects for harness PRs)."
say "Record the same three values locally so you can run the package on the golden case yourself"
say "(.env is git-ignored and guard-protected; a lane never reads it)."
ask FOUNDER_LLM_BASE_URL "OpenAI-compatible base URL (e.g. https://api.example.com/v1):"
ask FOUNDER_LLM_MODEL "Model name (the bake-off reference, T14; a provisional one is fine):"
ask_secret FOUNDER_LLM_API_KEY "API key (hidden):"
write_env FOUNDER_LLM_BASE_URL "$FOUNDER_LLM_BASE_URL"
write_env FOUNDER_LLM_MODEL "$FOUNDER_LLM_MODEL"
write_env FOUNDER_LLM_API_KEY "$FOUNDER_LLM_API_KEY"
pause "Press Enter when the three variables, internet access and the PR-author setting are saved on app.kiro.dev."

# ── 4 ────────────────────────────────────────────────────────────────────────
stage "${STAGE_NAMES[3]}"
say "The dispatcher posts the /kiro allocation comment and opens adopted pull requests with YOUR token:"
say "Kiro Web ignores a comment or label made by github-actions[bot] (nhan M-1)."
open_url "https://github.com/settings/personal-access-tokens/new"
step "Token name: founder-vn harness dispatch. Resource owner: $ORG. Expiration: your choice (the dispatcher's preflight reports an expired token)."
step "Repository access: Only select repositories → founder-vn."
step "Repository permissions: Issues → Read and write; Pull requests → Read and write; Contents → Read-only; Metadata → Read-only (automatic)."
step "Generate token, then copy it (it is shown once)."
ask_secret HARNESS_DISPATCH_TOKEN "Paste the token (hidden):"
local tok_user
if tok_user=$(GH_TOKEN="$HARNESS_DISPATCH_TOKEN" gh api user --jq .login 2>/dev/null) && [[ -n "$tok_user" ]]; then
  say "token authenticates as $tok_user"
  if GH_TOKEN="$HARNESS_DISPATCH_TOKEN" gh api "repos/$REPO/issues?per_page=1" >/dev/null 2>&1; then say "token reads issues of $REPO"; else warn "token cannot read issues of $REPO: check Repository access and Issues permission"; fi
  if GH_TOKEN="$HARNESS_DISPATCH_TOKEN" gh api "repos/$REPO/branches/main" >/dev/null 2>&1; then say "token reads contents of $REPO"; else warn "token cannot read contents of $REPO: Contents → Read-only is needed for adopted pull requests (nhan M-48)"; fi
else
  warn "GitHub rejected the token; set the secret anyway and fix it later if the dispatcher's preflight complains."
fi
set_secret HARNESS_DISPATCH_TOKEN "$HARNESS_DISPATCH_TOKEN"

# ── 5 ────────────────────────────────────────────────────────────────────────
stage "${STAGE_NAMES[4]}"
say "HARNESS_WEB_REVIEW=on lets the orchestrator post review and address turns; 'off' pauses them without touching code."
set_var HARNESS_WEB_REVIEW on
say "HARNESS_DISPATCH=off keeps the dispatcher from allocating new lanes (FV-D13) until stage 10 turns it on;"
say "review and merge of lanes already running are not affected."
set_var HARNESS_DISPATCH off

# ── 6 ────────────────────────────────────────────────────────────────────────
stage "${STAGE_NAMES[5]}"
say "The three workflows declare their permissions explicitly, so the repository default does not have to be"
say "'read and write'. Pull requests are opened with your token, never with GITHUB_TOKEN, so 'Allow GitHub Actions"
say "to create and approve pull requests' can stay off. This stage only reports what is set."
local perms; perms=$(gh api "repos/$REPO/actions/permissions/workflow" 2>/dev/null || echo '{}')
say "repository default_workflow_permissions: $(jq -r '.default_workflow_permissions // "?"' <<< "$perms"); can_approve_pull_request_reviews: $(jq -r '.can_approve_pull_request_reviews // "?"' <<< "$perms")"
local operms; operms=$(gh api "orgs/$ORG/actions/permissions/workflow" 2>/dev/null || echo '{}')
say "organisation default_workflow_permissions: $(jq -r '.default_workflow_permissions // "?"' <<< "$operms")"
note "If a Gate run later fails on 'Resource not accessible by integration', open"
note "https://github.com/$REPO/settings/actions and set Workflow permissions to Read and write."
pause

# ── 7 ────────────────────────────────────────────────────────────────────────
stage "${STAGE_NAMES[6]}"
say "Ticket T01 (#2) ends with v0.1.0 on PyPI through trusted publishing. Without a pending publisher the lane"
say "cannot finish that criterion and will report BLOCKED, by design. You can do this now or when T01 asks."
if confirm "Set up the PyPI pending publisher now?"; then
  open_url "https://pypi.org/manage/account/publishing/"
  step "Under 'Add a new pending publisher' → GitHub: PyPI project name founder-vn; Owner $ORG; Repository name founder-vn;"
  step "Workflow name: release.yml (T01's lane must name its release workflow so, or you edit the publisher afterwards); Environment name: pypi (optional)."
  step "Add. The publisher stays pending until the first release creates the project."
  pause "Press Enter when the pending publisher is listed."
else
  SKIPPED+=("PyPI pending publisher for founder-vn (https://pypi.org/manage/account/publishing/): T01 will BLOCK on its release criterion until it exists")
fi

# ── 8 ────────────────────────────────────────────────────────────────────────
stage "${STAGE_NAMES[7]}"
say "Ticket #5 (T04, golden case idea.md) is ready-for-human and blocks seven skill tickets (T11–T17):"
say "the loop stops after about nine tickets if it is still open."
gh issue view 5 --repo "$REPO" --json number,title,labels --jq '"  #\(.number) \(.title) [\([.labels[].name] | join(", "))]"' 2>/dev/null || true
note "Do it early; the loop does not need it today."
say ""
say "Dry run of the dispatcher with the token (nothing is written):"
if [[ -n "${HARNESS_DISPATCH_TOKEN:-}" ]]; then
  HARNESS_DISPATCH_TOKEN="$HARNESS_DISPATCH_TOKEN" bash scripts/harness/dispatch.sh --repo "$REPO" 2>&1 | grep -E '^gathered|"pick"|"frontier"|dispatch token|dry run' | sed 's/^/    /' || true
else
  bash scripts/harness/dispatch.sh --repo "$REPO" 2>&1 | grep -E '^gathered|"pick"|"frontier"|dispatch token|dry run' | sed 's/^/    /' || true
fi
say ""
say "The loop starts in stage 10. Before that, stage 9 protects main."
pause

# ── 9 ────────────────────────────────────────────────────────────────────────
stage "${STAGE_NAMES[8]}"
say "The PreToolUse guard (.kiro/hooks/guard.sh) does not run inside the Kiro Web sandbox (measured 2026-11-22,"
say "FV-M-6), so nothing on the lane's side stops a direct push to main except the rules in its message."
say "GitHub branch protection does: pull requests only (0 required approvals, so the machine merger still merges),"
say "no force pushes, no deletion. You, the operator, go through pull requests too (as PR #21 did)."
local prot; prot=$(gh api "repos/$REPO/branches/main/protection" --jq '.required_pull_request_reviews != null' 2>/dev/null || echo false)
if [[ "$prot" == true ]]; then
  say "main already requires pull requests."
elif confirm "Protect main now (require pull request, no force push, no deletion)?"; then
  if printf '%s' '{"required_status_checks":null,"enforce_admins":false,"required_pull_request_reviews":{"required_approving_review_count":0},"restrictions":null,"allow_force_pushes":false,"allow_deletions":false}' \
     | gh api --method PUT "repos/$REPO/branches/main/protection" --input - >/dev/null 2>&1; then
    say "main protected: pull requests required (0 approvals), no force pushes, no deletions."
  else
    SKIPPED+=("branch protection on main (https://github.com/$REPO/settings/branches): require a pull request before merging, 0 approvals")
    warn "could not set branch protection by API; set it by hand (link in the closing summary)"
  fi
else
  SKIPPED+=("branch protection on main (https://github.com/$REPO/settings/branches): require a pull request before merging, 0 approvals")
fi

# ── 10 ───────────────────────────────────────────────────────────────────────
stage "${STAGE_NAMES[9]}"
say "Three workflows carry the loop: gate.yml (always on), after-gate.yml (the quarter-hourly cron, which GitHub fires rarely: FV-M-8) and frontier-dispatch.yml."
say "Both dispatching workflows were disabled while the harness was built; the dispatcher also reads HARNESS_DISPATCH."
local wf
for wf in after-gate.yml frontier-dispatch.yml; do
  if gh workflow enable "$wf" --repo "$REPO" >/dev/null 2>&1; then say "enabled $wf"; else warn "could not enable $wf (gh workflow enable $wf)"; fi
done
if confirm "Start the loop now: set HARNESS_DISPATCH=on? The next sweep (the cron, which may take hours, or a manual frontier-dispatch run) allocates ticket #2 to Kiro Web."; then
  set_var HARNESS_DISPATCH on
  say "To allocate without waiting for the cron:"
  note "  gh workflow run frontier-dispatch.yml --repo $REPO -f apply=true"
  say "To pause again at any time:"
  note "  gh variable set HARNESS_DISPATCH --body off --repo $REPO"
else
  say "Loop left paused (HARNESS_DISPATCH=off). Start it later with:"
  note "  gh variable set HARNESS_DISPATCH --body on --repo $REPO && gh workflow run frontier-dispatch.yml --repo $REPO -f apply=true"
fi
pause

finish
}

run_wizard "$@"; exit
